def resumen_numeros(n):
    '''Retorna (suma de cuadrados de pares, lista de cubos de impares) en range(n).'''
    cuadrados = []
    for x in range(n):
        if x % 2 == 0:
            cuadrados.append(x**2)
    suma = sum(cuadrados)

    cubos = []
    for x in range(n):
        if x % 2 == 1:
            cubos.append(x**3)

    return suma, cubos

