from dataclasses import dataclass

@dataclass
class Producto:
    sku: str
    nombre: str
    precio: float
    stock: int

    def valor_total(self) -> float:
        return self.precio * self.stock

class Inventario:
    """Dict interno + interfaz limpia. Búsqueda O(1), datos tipados."""
    def __init__(self):
        self._items: dict = {}

    def agregar(self, p: Producto) -> None:
        self._items[p.sku] = p

    def buscar(self, sku: str):
        return self._items.get(sku)   # None si no existe, sin KeyError

    def actualizar_stock(self, sku: str, cantidad: int) -> None:
        if (p := self._items.get(sku)) is None:
            raise KeyError(f'SKU inexistente: {sku}')
        p.stock = cantidad

    def bajo_minimo(self, minimo: int = 5):
        return [p for p in self._items.values() if p.stock < minimo]

    def valor_total(self) -> float:
        return sum(p.valor_total() for p in self._items.values())

